INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (2498, 'preparation', 1, 'hi', 'preparation_steps', '1) द्रव्य को साफ करके छाया में सुखाएँ। 2) आवश्यकतानुसार कूट‑पीसकर चूर्ण/काढ़ा आदि तैयार करें। 3) मात्रा व अवधि के लिए योग्य वैद्य की सलाह लें।', 'auto', 'manual', '2026-01-17 06:36:49');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (2499, 'preparation', 1, 'mr', 'preparation_steps', '1) द्रव्य स्वच्छ करून सावलीत वाळवा. 2) गरजेनुसार कुटून‑दळून चूर्ण/काढा इ. तयार करा. 3) मात्रा व कालावधीसाठी पात्र वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:49');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (2500, 'preparation', 1, 'hi', 'notes', 'परंपरागत उपयोगों के आधार पर सहायक जानकारी। व्यक्तिगत प्रकृति/दोष व अन्य दवाओं के अनुसार मात्रा‑निर्धारण हेतु वैद्य से परामर्श करें।', 'auto', 'manual', '2026-01-17 06:36:49');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (2501, 'preparation', 1, 'mr', 'notes', 'पारंपरिक वापरांवर आधारित पूरक माहिती. व्यक्तीची प्रकृती/दोष व इतर औषधांनुसार मात्रा ठरवण्यासाठी वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:49');
