INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (3970, 'preparation', 185, 'hi', 'preparation_steps', '1) द्रव्य को साफ करके छाया में सुखाएँ। 2) आवश्यकतानुसार कूट‑पीसकर चूर्ण/काढ़ा आदि तैयार करें। 3) मात्रा व अवधि के लिए योग्य वैद्य की सलाह लें।', 'auto', 'manual', '2026-01-17 06:36:53');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (3971, 'preparation', 185, 'mr', 'preparation_steps', '1) द्रव्य स्वच्छ करून सावलीत वाळवा. 2) गरजेनुसार कुटून‑दळून चूर्ण/काढा इ. तयार करा. 3) मात्रा व कालावधीसाठी पात्र वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:53');
