INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4011, 'preparation', 190, 'mr', 'preparation_steps', '1) द्रव्य स्वच्छ करून सावलीत वाळवा. 2) गरजेनुसार कुटून‑दळून चूर्ण/काढा इ. तयार करा. 3) मात्रा व कालावधीसाठी पात्र वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:53');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4012, 'preparation', 190, 'hi', 'notes', 'परंपरागत उपयोगों के आधार पर सहायक जानकारी। व्यक्तिगत प्रकृति/दोष व अन्य दवाओं के अनुसार मात्रा‑निर्धारण हेतु वैद्य से परामर्श करें।', 'auto', 'manual', '2026-01-17 06:36:53');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4013, 'preparation', 190, 'mr', 'notes', 'पारंपरिक वापरांवर आधारित पूरक माहिती. व्यक्तीची प्रकृती/दोष व इतर औषधांनुसार मात्रा ठरवण्यासाठी वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:53');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4014, 'preparation', 190, 'hi', 'dosage_json', '{"adult": "सामान्यतः 1–3 ग्राम, दिन में 1–2 बार (केवल वैद्यकीय मार्गदर्शन में)।", "child": "बच्चों के लिए केवल योग्य वैद्य की देखरेख में, आयु/वजन के अनुसार।"}', 'auto', 'manual', '2026-01-17 06:36:53');
