INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4260, 'preparation', 221, 'hi', 'notes', 'परंपरागत उपयोगों के आधार पर सहायक जानकारी। व्यक्तिगत प्रकृति/दोष व अन्य दवाओं के अनुसार मात्रा‑निर्धारण हेतु वैद्य से परामर्श करें।', 'auto', 'manual', '2026-01-17 06:36:54');
