INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4628, 'preparation', 267, 'hi', 'notes', 'परंपरागत उपयोगों के आधार पर सहायक जानकारी। व्यक्तिगत प्रकृति/दोष व अन्य दवाओं के अनुसार मात्रा‑निर्धारण हेतु वैद्य से परामर्श करें।', 'auto', 'manual', '2026-01-17 06:36:55');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4629, 'preparation', 267, 'mr', 'notes', 'पारंपरिक वापरांवर आधारित पूरक माहिती. व्यक्तीची प्रकृती/दोष व इतर औषधांनुसार मात्रा ठरवण्यासाठी वैद्यांचा सल्ला घ्या.', 'auto', 'manual', '2026-01-17 06:36:55');
