INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4710, 'preparation', 277, 'hi', 'dosage_json', '{"adult": "सामान्यतः 1–3 ग्राम, दिन में 1–2 बार (केवल वैद्यकीय मार्गदर्शन में)।", "child": "बच्चों के लिए केवल योग्य वैद्य की देखरेख में, आयु/वजन के अनुसार।"}', 'auto', 'manual', '2026-01-17 06:36:55');
INSERT OR REPLACE INTO entity_i18n (id, entity_type, entity_id, lang, field, text, status, source, updated_at) VALUES (4711, 'preparation', 277, 'mr', 'dosage_json', '{"adult": "साधारणतः 1–3 ग्रॅम, दिवसातून 1–2 वेळा (फक्त वैद्यकीय मार्गदर्शनात)।", "child": "मुलांसाठी फक्त पात्र वैद्यांच्या देखरेखीखाली, वय/वजनानुसार."}', 'auto', 'manual', '2026-01-17 06:36:55');
